    fun templates(base: List<ExerciseTemplate>): List<ExerciseTemplate> {
        val profiles = base.associateBy { it.englishName }
        return machines.flatMap { model ->
            val title = if (model.name.startsWith(model.manufacturer)) model.name else "${model.manufacturer} ${model.name}"
            val code = if (model.manufacturer == "Technogym") model.sourceUrl.substringAfterLast('_').removeSuffix(".html") else ""
            if (model.manual) listOf(ExerciseTemplate(title, "Regionen manuell auswählen", ExerciseEquipment.MACHINE,
                emptyList(), aliases = code, manufacturer = model.manufacturer, sourceUrl = model.sourceUrl,
                trackingModeOverride = if (model.duration) TrackingMode.DURATION else null))
            else model.movements.map { movement ->
                val profile = profiles.getValue(movement)
                val equipment = when {
                    profile.equipment == ExerciseEquipment.CARDIO -> ExerciseEquipment.CARDIO
                    profile.equipment == ExerciseEquipment.CABLE -> ExerciseEquipment.CABLE
                    else -> ExerciseEquipment.MACHINE
                }
                profile.copy(englishName = title + if (model.movements.size > 1) " · $movement" else "",
                    equipment = equipment, aliases = profile.aliases + "; " + model.name + "; " + code,
                    manufacturer = model.manufacturer, sourceUrl = model.sourceUrl, baseExerciseName = movement)
            }
        }
    }
